export const PAPERS: PaperInput[] = [
  {"id":"2609.35259","title":"On-Policy or Off-Policy Learning? A Systematic Study of Distillation Dynamics","up":168,"href":"https://arxiv.org/abs/2609.35259","abstract":"On-policy learning has been argued to reduce catastrophic forgetting, produce sparser parameter updates, and improve generalisation. However, existing comparisons between supervised fine-tuning and reinforcement learning vary many factors simultaneously, making the contribution of rollout policy difficult to isolate. We study the effect of rollout policy in a controlled strong-to-weak distillation setting, by independently varying rollout policy, token-level KL direction, and learning rate across the Llama3 and Qwen2.5 model families and reasoning tasks spanning scientific, medical, and arithm","pdfUrl":"https://arxiv.org/pdf/2609.35259","primaryCategory":"cs.LG","crossrefDoi":"https://doi.org/10.1109/tnnls.2024.3373749/mm1"},
  {"id":"2610.01762","title":"OneStreamer: Unifying Perception, Memory, and Proactive Response in Streaming Video Interaction","up":163,"href":"https://arxiv.org/abs/2610.01762","abstract":"Streaming video LLMs must retain evidence before its relevance to future tasks is known and respond when sufficient evidence becomes available. The challenge is to form reusable factual memory without compromising real-time perception. We introduce OneStreamer, which jointly learns query-independent evidence recording and task response through a shared proactive generation process. Its Proactive Hierarchical Caption Memory (PHCM) produces time-grounded local-detail captions and summaries of completed events. Streaming caption targets supervise the interpretation of observed video prefixes duri","pdfUrl":"https://arxiv.org/pdf/2610.01762","primaryCategory":"cs.CV"},
  {"id":"2609.36585","title":"Transformers Stop Thinking Too Early, and a Tiny LoRA Fixes It","up":63,"href":"https://arxiv.org/abs/2609.36585","abstract":"Pretrained transformers use little of their depth to follow references in context. Thirteen base models reliably follow only 1.4-3.6 lines, and extra pretrained loops add little. A task-trained rank-8 LoRA at one early layer extends this computation with all model weights frozen. Qwen3-8B improves from 15.5% to 99% exact accuracy on 24-line chains; a longer-trained LoRA reaches 50 lines. Ouro-1.4B reaches 60 lines after four loops and at least 160 after eight. The LoRA starts a relay: program lines pass on their chain identity through a short range of middle layers. Frozen heads read progressi","pdfUrl":"https://arxiv.org/pdf/2609.36585","primaryCategory":"cs.AI"},
  {"id":"2609.37533","title":"E-MoE: Enhanced Mixture-of-Experts for Non-Factorized Diffusion Language Models","up":59,"href":"https://arxiv.org/abs/2609.37533","abstract":"Masked diffusion models (MDMs) generate sequences by progressively unmasking several tokens per denoising step, but their reverse process is typically factorized over positions, limiting sample quality in the few-step regime where diffusion's speed advantage over autoregressive decoding matters most. A recent line of work introduces a continuous Gaussian latent, trained as a variational autoencoder, to capture correlations across positions, but such approaches are prone to posterior collapse, where the latent is silently ignored. We propose Enhanced Mixture-of-Experts (E-MoE), which builds the","pdfUrl":"https://arxiv.org/pdf/2609.37533","primaryCategory":"cs.CL"},
  {"id":"2610.00574","title":"Make Sparse Rewards Count: Density-Aware Reward Aggregation for Multi-Reward RL","up":50,"href":"https://arxiv.org/abs/2610.00574","abstract":"Multi-reward reinforcement learning trains large language models to satisfy multiple behavioral objectives simultaneously. Reward-wise normalization, as used in GDPO, preserves reward-specific relative information within rollout groups, but different objectives can still exhibit uneven learning progress. We study this behavior through advantage energy, the sum of a reward's squared advantages over a batch. Under idealized GDPO normalization, we show that this energy is proportional to active-group density: the fraction of rollout groups in which the reward provides nonzero relative advantages.","pdfUrl":"https://arxiv.org/pdf/2610.00574","primaryCategory":"cs.LG"},
  {"id":"2609.39378","title":"EgoTools: Towards Tool-Centric Reasoning in Real-World Egocentric Videos","up":46,"href":"https://arxiv.org/abs/2609.39378","abstract":"Real-world embodied tasks, from everyday activities to professional procedures, require agents to act under physical constraints while tracking evolving object and task states. Tool use sits at the heart of such tasks, as many everyday and professional activities are tool-mediated. Understanding them requires reasoning about affordances, hand-tool-object geometry, procedural progress, and causal effects on target objects. Yet despite strong performance on perception-oriented video tasks such as captioning and general video QA, current multimodal video models remain limited in this form of tool","pdfUrl":"https://arxiv.org/pdf/2609.39378","primaryCategory":"cs.CV"},
  {"id":"2610.00812","title":"Video Generation Models: A Survey of Post-Training and Alignment","up":44,"href":"https://arxiv.org/abs/2610.00812","abstract":"Video generation has rapidly progressed from short, low-quality clips to high-resolution, long-duration sequences with complex spatiotemporal dynamics. Despite strong generative priors learned through large-scale pretraining, pretrained video models often fail to reliably follow human intent, maintain temporal coherence, or satisfy physical and safety constraints. Compared with image and text generation, alignment in video generation presents unique challenges, including error accumulation over time, motion-appearance coupling, multi-objective trade-offs, and limited supervision for temporal p","pdfUrl":"https://arxiv.org/pdf/2610.00812","primaryCategory":"cs.CV"},
  {"id":"2610.02196","title":"InterEvolve: Test-Time Evolution of Reward Programs for Humanoid Loco-Manipulation","up":43,"href":"https://arxiv.org/abs/2610.02196","abstract":"We study test-time evolution for humanoid loco-manipulation: solving tasks that a controller was never trained for by repurposing its existing skills, improving from its own attempts, and retaining what it learns, without retraining. Our key insight is that a broad controller already holds much of the competence a new task needs, and that this competence becomes accessible through an interface between planning and control that is expressive enough to specify contact-rich, multi-stage interactions, yet executable and measurable enough that execution feedback can guide planning from experience. ","pdfUrl":"https://arxiv.org/pdf/2610.02196","primaryCategory":"cs.RO"},
  {"id":"2609.32019","title":"Decentralized Master-Mind: Joint Action Refinement through Iterative Intent Denoising in Multi-Agent Pathfinding","up":42,"href":"https://arxiv.org/abs/2609.32019","abstract":"Decentralized multi-agent path finding (MAPF) with communication requires agents to reach individual goals without collisions under partial observability. Learnable policies trained on expert data provide an effective approach to this problem. However, when several coordinated joint actions are valid in the same context, independently sampling from per-agent distributions can recombine locally valid choices into incompatible joint actions. This failure can arise from the final sampling mechanism even when the per-agent action distributions are learned correctly. DMM (Decentralized Master-Mind)","pdfUrl":"https://arxiv.org/pdf/2609.32019","primaryCategory":"cs.AI"},
  {"id":"2609.32993","title":"X-Tree: Tokenizing Reusable Experience for Efficient Agent Generalization","up":42,"href":"https://arxiv.org/abs/2609.32993","abstract":"Multi-step agents are trained on flat action streams: SFT and RLVR weight every token uniformly and ignore the sub-procedures that recur across tasks, the hierarchy that lets humans plan top-down from reusable routines. This structure sits unused, and flat training uses each scarce trajectory less fully than its content allows. Recent agents do use that structure, but only as LLM-written skills in context, never in the weights, so their gains do not generalize beyond retrieval. We instead recover this hierarchy from the data itself and train on it, with no LLM calls. Following text tokenizers,","pdfUrl":"https://arxiv.org/pdf/2609.32993","primaryCategory":"cs.AI"},
  {"id":"2609.36388","title":"Persona Dosing: Calibrated Activation Steering for Graded Trait Control","up":40,"href":"https://arxiv.org/abs/2609.36388","abstract":"An activation-steering coefficient sets intervention strength, but requesting a particular degree of persona expression requires a behavioral scale. We study persona dosing: controlling a language model through a trait description and a requested mean intensity. PersonaDose specializes a shared, description-conditioned FLAS controller on persona responses, then calibrates its flow time against measured trait expression. Training responses are not paired with requested target intensities. Across Llama-3.1-8B, Qwen3-8B, and Gemma-3-4B, PersonaDose raises core-trait expression at the Persona Vect","pdfUrl":"https://arxiv.org/pdf/2609.36388","primaryCategory":"cs.AI"},
  {"id":"2610.01939","title":"Fewer Tokens, Better Action: GPT-6 Astra Robot Agents with 14% Higher Success Rate but 65% Fewer Tokens","up":34,"href":"https://arxiv.org/abs/2610.01939","abstract":"Vision language model (VLM) agents can control robots through visual feedback and action primitives, but repeated model invocations and redundant observations incur substantial token overhead. We introduce PyRUA-Lean, an interactive code-execution framework that couples feedback-driven primitive composition with selective observation: the agent composes classical robot primitives and learned vision-language-action (VLA) policies into Python cells that perform conditional checks and local retries, returning only explicitly requested images and state feedback for replanning. Across 700 simulated","pdfUrl":"https://arxiv.org/pdf/2610.01939","primaryCategory":"cs.CV"},
  {"id":"2606.10953","title":"Architect-Ant: Editable Automatic Furnishing of Architectural Floor Plans","up":27,"href":"https://arxiv.org/abs/2606.10953","abstract":"Furnished floor plans support real-estate visualization, interior design, and architectural workflows, yet automatic furnishing remains challenged by limited real-world data and the need to satisfy interacting geometric and functional constraints. We ask whether professional furnishing knowledge can be learned from real floor plans using a pretrained model, enabling direct constraint-aware layout generation without relying on costly iterative agentic inference. We introduce AntPlan, a curated dataset of 505 real professional architectural floor plans with dense furniture annotations spanning 9","pdfUrl":"https://arxiv.org/pdf/2606.10953","primaryCategory":"cs.AI"},
  {"id":"2610.02201","title":"SILSA: Sliding-Window Slice Latents for Topology-Preserving High-Resolution 3D Generation","up":27,"href":"https://arxiv.org/abs/2610.02201","abstract":"High-resolution 3D generation increasingly relies on voxel latents and multi-stage pipelines that first predict active structure and then synthesize local geometry. While effective, this design fragments continuous surfaces into many local tokens, inflates generation cost, and often weakens topological consistency for thin or highly connected shapes. We introduce SILSA, a topology-aware 3D generation framework that represents shapes with compact sliding-window slice latents. Instead of generating expensive voxel tokens, SILSA uses a fixed set of overlapping slices along the three canonical axe","pdfUrl":"https://arxiv.org/pdf/2610.02201","primaryCategory":"cs.CV"},
  {"id":"2609.36820","title":"CorrGRPO: Correlation-Normalized GRPO for Multi-Reward Learning","up":25,"href":"https://arxiv.org/abs/2609.36820","abstract":"Group Relative Policy Optimization (GRPO) is widely used to train reasoning language models, where it computes advantages by centering and normalizing rewards across rollouts of the same prompt. For multiple rewards, GRPO sums the reward components and normalizes the total reward by its within-group standard deviation. The corresponding variance equals the sum of all pairwise reward covariances. For a fixed centered reward, larger aggregate covariance produces smaller advantages, and vice versa, allowing update magnitudes to adapt to reward dependence. However, correlated rewards with large sc","pdfUrl":"https://arxiv.org/pdf/2609.36820","primaryCategory":"cs.LG"},
  {"id":"2610.02185","title":"Decoding Looped Transformers Better for (Almost) Free","up":25,"href":"https://arxiv.org/abs/2610.02185","abstract":"Looped Transformers achieve parameter efficiency by repeatedly executing a shared block across recurrent loops. Each loop yields an intermediate representation decodable for the same next token, yet standard decoding discards earlier states. Because earlier loops embody less computation, recurrence inherently supplies aligned weak-and-strong prediction pairs without auxiliary models or external training. We introduce LoopCD, a training-free contrastive decoding framework that guides token selection by contrasting the final prediction with an earlier recurrent pass, operating either in logit sp","pdfUrl":"https://arxiv.org/pdf/2610.02185","primaryCategory":"cs.LG"},
  {"id":"2609.40362","title":"Multimodal Flow: Unified Flow Modeling of Language and Vision in Embedding Spaces","up":23,"href":"https://arxiv.org/abs/2609.40362","abstract":"We present Multimodal Flow, a fully continuous generative model of language and vision. Most unified multimodal models either model both language and quantized images as discrete tokens or combine discrete language prediction with continuous image generation. The former introduces a visual quantization bottleneck. The latter requires modality-dependent objectives and sampling procedures. Fully continuous modeling avoids these trade-offs and enables a shared generative process, but remains underexplored for multimodal pretraining. Multimodal Flow introduces a unified continuous architecture tha","pdfUrl":"https://arxiv.org/pdf/2609.40362","primaryCategory":"cs.CV"},
  {"id":"2610.01092","title":"Ego2Act: Evaluating Goal-Directed Manipulation in Egocentric Video Generation","up":21,"href":"https://arxiv.org/abs/2610.01092","abstract":"Video generation models are increasingly being explored as world simulators for embodied planning and learning. To do so effectively, these models must not only generate visually appealing frames, but also predict how environments dynamically evolve when executing goal-directed actions. While evaluating these capabilities is crucial, existing benchmarks focus mainly on single short actions or step-by-step instructions. This leaves multi-step physical reasoning underexplored, especially in egocentric video generation that requires planning to simulate proper execution to accomplish high-level g","pdfUrl":"https://arxiv.org/pdf/2610.01092","primaryCategory":"cs.CV"},
  {"id":"2610.02122","title":"Argo-Bench: Evaluating Data Agents on Enterprise-Scale Workflows","up":21,"href":"https://arxiv.org/abs/2610.02122","abstract":"Real-world enterprise data science and analytics workflows require reasoning across dozens of tables, performing statistical analyses, and acting on the results. Established text-to-SQL benchmarks evaluate query generation alone, and audits have found their answer keys frequently wrong. Because real enterprise warehouses are too sensitive to release, these benchmarks are built on public datasets where a business event fits in a single table. We introduce Argo-Bench, an evaluation framework comprising 210 data science and analytics tasks. Drawing on public data, peer-reviewed industry literatur","pdfUrl":"https://arxiv.org/pdf/2610.02122","primaryCategory":"cs.CL"},
  {"id":"2610.02148","title":"Omni-Embed-Mini: Binding Modalities Without Forgetting via Dense Distillation","up":19,"href":"https://arxiv.org/abs/2610.02148","abstract":"Extending a text embedding model to new modalities typically degrades text retrieval quality, and existing omni-modal embedders compensate with multi-billion parameters. We present Omni-Embed-Mini, a 0.9B-parameter model that maps text, speech, audio, images, video, and visually-rich documents into a single shared cosine space without updating any text-side parameter. Our key insight is that the teacher signal requires no separate embedding model: each media sample is paired with a dense cascaded caption, and the teacher target is simply the frozen backbone's own embedding of that caption. Bec","pdfUrl":"https://arxiv.org/pdf/2610.02148","primaryCategory":"cs.CV"},
  {"id":"2610.00559","title":"PhysVista: Benchmarking Physical Intelligence in VLMs via a Perception-Reasoning-Assessment Loop","up":17,"href":"https://arxiv.org/abs/2610.00559","abstract":"Vision-Language Models (VLMs) have shown strong multimodal reasoning capabilities, yet whether they truly capture the physical consistency underlying real-world dynamics remains unclear. Existing benchmark paradigms often suffer from fragmented evaluation, focusing on isolated cognitive stages while overlooking the inherent synergy between perception, reasoning, and physical judgment. The lack of a holistic perspective limits the ability to diagnose whether VLMs can reliably evaluate the physical authenticity of emerging generative models. To address these issues, we introduce PhysVista, a ben","pdfUrl":"https://arxiv.org/pdf/2610.00559","primaryCategory":"cs.CV"},
  {"id":"2609.38987","title":"Smaller Models, Better Rejects: Preference Distillation Scaling","up":15,"href":"https://arxiv.org/abs/2609.38987","abstract":"Preference distillation typically treats a teacher response as preferred and the student's own response as rejected. This assumes that self-generated failures are the most informative negatives and that rejects must come from a model at least as large as the student, making generation costly at scale. We find neither assumption holds: across students from 7B to 72B, smaller frozen models generate rejects with less inference compute yet train stronger students than self-generated rejects, before and after sequence-level knowledge distillation, on code generation and mathematical reasoning. To e","pdfUrl":"https://arxiv.org/pdf/2609.38987","primaryCategory":"cs.LG"},
  {"id":"2609.39687","title":"Better Supervision Is Nearby: Neighborhood On-Policy Self-Distillation","up":15,"href":"https://arxiv.org/abs/2609.39687","abstract":"On-policy self-distillation (OPSD) trains mathematical reasoning models using a privileged teacher that sees a reference solution and supervises student-sampled prefixes. Standard OPSD uses one fixed parameter setting at every state, but nearby settings may offer additional supervision. We find that local parameter perturbations reveal complementary reference-aligned corrections under the same reference context. Different experts supply these corrections at different reference positions. Their pool covers more such positions than the unperturbed privileged teacher. We introduce Neighborhood OP","pdfUrl":"https://arxiv.org/pdf/2609.39687","primaryCategory":"cs.CL"},
  {"id":"2610.02117","title":"Where-OPD: Spatially Guided On-Policy Self-Distillation of MLLMs with Synthetic Scenes","up":14,"href":"https://arxiv.org/abs/2610.02117","abstract":"On-policy self-distillation has recently emerged as an effective approach for improving language-model reasoning by supervising students with a frozen or EMA version of themselves that receives privileged information. Its application to multimodal large language models (MLLMs), however, remains largely unexplored. Recent approaches use privileged visual information, such as image crops corresponding to a question, to improve fine-grained perception, but their gains are confined to tasks that benefit from such visual zooming and require either human-annotated grounding data or external teacher ","pdfUrl":"https://arxiv.org/pdf/2610.02117","primaryCategory":"cs.CV"},
];

